#!/usr/bin/env python3
"""
todo.py -- a small command-line to-do list manager.

Commands:
    add <text>   Append a new task.
    list         Print all tasks.
    done <id>    Mark a task complete.

Tasks are persisted as JSON in tasks.json, located next to this script
(regardless of the current working directory).
"""

import json
import os
import sys

TASKS_FILE = os.path.join(os.path.dirname(os.path.abspath(__file__)), "tasks.json")

USAGE = "Usage: todo.py {add|list|done} ...\n"


class CorruptTasksFile(Exception):
    """Raised when tasks.json exists but is invalid JSON or does not match the schema."""


def _validate_task(task):
    if not isinstance(task, dict):
        return False
    if set(task.keys()) != {"id", "text", "done"}:
        return False
    task_id = task["id"]
    if isinstance(task_id, bool) or not isinstance(task_id, int):
        return False
    if task_id < 1:
        return False
    text = task["text"]
    if not isinstance(text, str) or len(text) < 1:
        return False
    done = task["done"]
    if not isinstance(done, bool):
        return False
    return True


def _validate_data(data):
    if not isinstance(data, dict):
        return False
    if set(data.keys()) != {"tasks"}:
        return False
    tasks = data["tasks"]
    if not isinstance(tasks, list):
        return False
    for task in tasks:
        if not _validate_task(task):
            return False
    return True


def load_tasks():
    """Return the list of tasks from TASKS_FILE, or [] if the file does not exist.

    Raises CorruptTasksFile if the file exists but is invalid JSON or does not
    match the expected schema.
    """
    if not os.path.exists(TASKS_FILE):
        return []

    try:
        with open(TASKS_FILE, "r", encoding="utf-8") as f:
            data = json.load(f)
    except (json.JSONDecodeError, ValueError):
        raise CorruptTasksFile()

    if not _validate_data(data):
        raise CorruptTasksFile()

    return data["tasks"]


def save_tasks(tasks):
    tasks_sorted = sorted(tasks, key=lambda t: t["id"])
    data = {"tasks": tasks_sorted}
    with open(TASKS_FILE, "w", encoding="utf-8") as f:
        json.dump(data, f, indent=2)
        f.write("\n")


def cmd_add(args):
    joined = " ".join(args)
    if joined.strip() == "":
        sys.stderr.write("Error: add requires <text> argument\n")
        return 2

    try:
        tasks = load_tasks()
    except CorruptTasksFile:
        sys.stderr.write("Error: tasks.json is corrupted\n")
        return 1

    new_id = (max((t["id"] for t in tasks), default=0)) + 1
    tasks.append({"id": new_id, "text": joined, "done": False})
    save_tasks(tasks)

    sys.stdout.write("Added task {}: {}\n".format(new_id, joined))
    return 0


def cmd_list(args):
    try:
        tasks = load_tasks()
    except CorruptTasksFile:
        sys.stderr.write("Error: tasks.json is corrupted\n")
        return 1

    if not tasks:
        sys.stdout.write("No tasks.\n")
        return 0

    for task in sorted(tasks, key=lambda t: t["id"]):
        status = "done" if task["done"] else "pending"
        sys.stdout.write("{} [{}] {}\n".format(task["id"], status, task["text"]))
    return 0


def cmd_done(args):
    if len(args) < 1:
        sys.stderr.write("Error: done requires <id> argument\n")
        return 2

    id_arg = args[0]
    try:
        task_id = int(id_arg)
    except ValueError:
        sys.stderr.write("Error: {} is not a valid task id\n".format(id_arg))
        return 2

    try:
        tasks = load_tasks()
    except CorruptTasksFile:
        sys.stderr.write("Error: tasks.json is corrupted\n")
        return 1

    target = None
    for task in tasks:
        if task["id"] == task_id:
            target = task
            break

    if target is None:
        sys.stderr.write("Error: task {} not found\n".format(task_id))
        return 1

    target["done"] = True
    save_tasks(tasks)

    sys.stdout.write("Task {} marked as done.\n".format(task_id))
    return 0


def main(argv):
    if not argv:
        sys.stderr.write(USAGE)
        return 2

    command, rest = argv[0], argv[1:]

    if command == "add":
        return cmd_add(rest)
    elif command == "list":
        return cmd_list(rest)
    elif command == "done":
        return cmd_done(rest)
    else:
        sys.stderr.write(USAGE)
        return 2


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

