def _configure_utf8_streams():
    """Best-effort: force stdout/stderr to UTF-8.

    Task text is arbitrary Unicode, but the process's default stdout/stderr
    encoding is inherited from the environment (e.g. PYTHONIOENCODING, or a
    non-UTF-8 locale) and may be more restrictive than UTF-8. Under such an
    encoding, writing non-ASCII task text with sys.stdout.write() would raise
    an uncaught UnicodeEncodeError. Reconfiguring both streams to UTF-8 (the
    encoding tasks.json itself is always written/read with) avoids that.
    """
    for stream in (sys.stdout, sys.stderr):
        reconfigure = getattr(stream, "reconfigure", None)
        if reconfigure is None:
            continue
        try:
            reconfigure(encoding="utf-8")
        except (ValueError, OSError):
            pass


